"""
Seed parts library with common, well-characterized sequence components.

These are loaded on app startup to provide a starting library for users.
"""
from typing import List

from core.models.parts import UTR5Part, KozakPart, CDSPart, UTR3Part, PolyAPart, SequencePart


def get_seed_parts() -> List[SequencePart]:
    """Return a list of seed parts to populate the library."""

    parts = []

    # ── 5' UTRs ────────────────────────────────────────────────────────────────

    # Strong constitutive 5'UTR from β-globin
    parts.append(UTR5Part(
        name="β-globin_5UTR",
        sequence="GTTGCTCCTTCGGGCTGCTGGGGTGAATAGTTCTGCCTTCGCGGCGCCGCCAAGTCCT",
        source="library",
    ))

    # CMV 5'UTR - very strong for mammalian expression
    parts.append(UTR5Part(
        name="CMV_5UTR",
        sequence="GACATTGATTATTGACTAGTTATTAATAGTAATCAATTACGGGGTCATTAGTTCATAGCCCATATATGGAGTTCCGCGTTACATAACTTACGGTAAATGGCCCGCCTGGCTGACCGCCCAACGACCCCCGCCCATTGACGTCAATAATGACGTATGTTCCCATAGTAACGCCAATAGGGACTTTCCATTGACGTC",
        source="library",
    ))

    # HBB 5'UTR - hemoglobin beta
    parts.append(UTR5Part(
        name="HBB_5UTR",
        sequence="ACATTTGCTTCTGACACAACTGTGTTCACTAGCAACCTCAAACAGACACCATGGTGCAT",
        source="library",
    ))

    # GAPDH 5'UTR - housekeeping gene
    parts.append(UTR5Part(
        name="GAPDH_5UTR",
        sequence="CGCTCTCTGCTCCTCCTGTTCGACAGTCAGCCGCATCTTCTTTTGCGTCGCCAGCCGAGCCACATCGCTC",
        source="library",
    ))

    # Minimal synthetic 5'UTR - very short, minimal structure
    parts.append(UTR5Part(
        name="Minimal_5UTR",
        sequence="GGGAAATAAGAGAGAAAAGAAGAGTAAGAAGAAATATAAGAGCCACC",
        source="library",
    ))

    # ── Kozak sequences ───────────────────────────────────────────────────────

    # Optimal Kozak consensus
    parts.append(KozakPart(
        name="Kozak_Optimal",
        sequence="GCCACCATG",
        source="library",
        consensus_score=1.0,
        matches_canonical=True,
    ))

    # Strong Kozak variant
    parts.append(KozakPart(
        name="Kozak_Strong",
        sequence="GCCGCCATG",
        source="library",
        consensus_score=0.95,
        matches_canonical=True,
    ))

    # Moderate Kozak
    parts.append(KozakPart(
        name="Kozak_Moderate",
        sequence="ACCATG",
        source="library",
        consensus_score=0.7,
        matches_canonical=False,
    ))

    # ── CDS ───────────────────────────────────────────────────────────────────

    # EGFP - Enhanced Green Fluorescent Protein (codon optimized)
    parts.append(CDSPart(
        name="EGFP_CDS",
        sequence="",
        source="library",
        has_start_codon=True,
        has_stop_codon=True,
    ))

    # Luciferase - reporter gene
    parts.append(CDSPart(
        name="Luciferase_CDS",
        sequence="",
        source="library",
        has_start_codon=True,
        has_stop_codon=True,
    ))

    # mCherry - red fluorescent protein
    parts.append(CDSPart(
        name="mCherry_CDS",
        sequence="",
        source="library",
        has_start_codon=True,
        has_stop_codon=True,
    ))

    # Short peptide tag - His6 tag
    parts.append(CDSPart(
        name="His6_Tag",
        sequence="ATGCATCATCATCATCATCATTAA",
        source="library",
        has_start_codon=True,
        has_stop_codon=True,
    ))

    # ── 3' UTRs ───────────────────────────────────────────────────────────────

    # β-globin 3'UTR - very stable
    parts.append(UTR3Part(
        name="β-globin_3UTR",
        sequence="",
        source="library",
    ))

    # SV40 polyA signal (short)
    parts.append(UTR3Part(
        name="SV40_3UTR",
        sequence="GATCCAGACATGATAAGATACATTGATGAGTTTGGACAAACCACAACTAGAATGCAGTGAAAAAAATGCTTTATTTGTGAAATTTGTGATGCTATTGCTTTATTTGTAACCATTATAAGCTGCAATAAACAAGTTAACAACAACAATTGCATTCATTTTATGTTTCAGGTTCAGGGGGAGGTGTGGGAGGTTTTTTAAAGCAAGTAAAACCTCTACAAATGTGGTA",
        source="library",
    ))

    # Human Growth Hormone 3'UTR
    parts.append(UTR3Part(
        name="hGH_3UTR",
        sequence="",
        source="library",
    ))

    # Albumin 3'UTR
    parts.append(UTR3Part(
        name="Albumin_3UTR",
        sequence="TGCCTGGCACTTGTCCCGAACAGTTGGGGGAGGGGAGGGAGTAGGTTGTGTGTGTTGGG",
        source="library",
    ))

    # ── Poly(A) tails ─────────────────────────────────────────────────────────

    # Standard 30A tail
    parts.append(PolyAPart(
        name="PolyA_30",
        sequence="A" * 30,
        source="library",
        tail_length=30,
        purity=1.0,
    ))

    # Long 60A tail
    parts.append(PolyAPart(
        name="PolyA_60",
        sequence="A" * 60,
        source="library",
        tail_length=60,
        purity=1.0,
    ))

    # Standard 120A tail (typical for mRNA)
    parts.append(PolyAPart(
        name="PolyA_120",
        sequence="A" * 120,
        source="library",
        tail_length=120,
        purity=1.0,
    ))

    # Short 15A tail
    parts.append(PolyAPart(
        name="PolyA_15",
        sequence="A" * 15,
        source="library",
        tail_length=15,
        purity=1.0,
    ))

    # Mixed tail (A-rich but not pure)
    parts.append(PolyAPart(
        name="PolyA_Mixed_50",
        sequence="AAAAAAAAACAAAAAAAAAACAAAAAAAAAACAAAAAAAAAACAAAAAAAAAA",
        source="library",
        tail_length=50,
        purity=0.94,
    ))

    return parts
